import { spawnSync } from 'node:child_process';
import { chmod, mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath, URL as NodeURL } from 'node:url';
import { describe, expect, it } from 'vitest';

const PROJECT_ROOT = fileURLToPath(new NodeURL('..', import.meta.url));

describe('Container entrypoint', () => {
  it('rejects missing executor settings', () => {
    const result = spawnSync('./bin/start-executor', {
      cwd: PROJECT_ROOT,
      env: { ...process.env, PATH: process.env.PATH }
    });

    expect(result.status).not.toBe(0);
    expect(result.stderr.toString()).toContain('CODEX_API_KEY is required');
  });

  it('rejects a missing remote URL', () => {
    const result = spawnSync('./bin/start-executor', {
      cwd: PROJECT_ROOT,
      env: {
        ...process.env,
        PATH: process.env.PATH,
        CODEX_API_KEY: 'executor-key',
        OPENAI_ENVIRONMENT_ID: 'env_1'
      }
    });

    expect(result.status).not.toBe(0);
    expect(result.stderr.toString()).toContain('OPENAI_REMOTE_URL is required');
  });

  it('starts the Codex executor with the configured environment', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'agents-api-executor-'));
    const codex = join(directory, 'codex');
    await writeFile(codex, '#!/bin/sh\nprintf "%s\\n" "$@"\n');
    await chmod(codex, 0o755);

    const result = spawnSync('./bin/start-executor', {
      cwd: PROJECT_ROOT,
      env: {
        ...process.env,
        PATH: `${directory}:${process.env.PATH}`,
        CODEX_API_KEY: 'executor-key',
        OPENAI_ENVIRONMENT_ID: 'env_1',
        OPENAI_REMOTE_URL: 'https://agents.example.test/v1'
      }
    });
    await rm(directory, { recursive: true, force: true });

    expect(result.status).toBe(0);
    expect(result.stdout.toString()).toBe(
      'exec-server\n--remote\nhttps://agents.example.test/v1\n--environment-id\nenv_1\n'
    );
  });
});

import { createHmac } from 'node:crypto';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import worker from '../src/index';
import {
  resetSpanAttributes,
  spanAttributes
} from './mocks/cloudflare-workers';

const WEBHOOK_SECRET = 'webhook-secret';
const envelope = {
  id: 'evt_123',
  object: 'event',
  created_at: 1_750_287_018
} as const;

function signedWebhook(event: unknown): Request {
  const payload = JSON.stringify(event);
  const webhookID = 'wh_1';
  const timestamp = String(Math.floor(Date.now() / 1_000));
  const signature = createHmac('sha256', WEBHOOK_SECRET)
    .update(`${webhookID}.${timestamp}.${payload}`)
    .digest('base64');

  return new Request('https://executor.test/webhook', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'webhook-id': webhookID,
      'webhook-timestamp': timestamp,
      'webhook-signature': `v1,${signature}`
    },
    body: payload
  });
}

function executorFixture(overrides: Record<string, string> = {}) {
  const executor = {
    prewarm: vi.fn(async () => undefined),
    update: vi.fn(async () => undefined),
    destroy: vi.fn(async () => undefined)
  };
  const getByName = vi.fn(() => executor);
  const env = {
    EXECUTORS: { getByName },
    OPENAI_EXECUTOR_API_KEY: 'executor-key',
    EXECUTOR_CLIENT_SECRET: 'client-secret',
    EXECUTOR_KEEP_ALIVE_SECONDS: '30',
    EXECUTOR_PREWARM_ENABLED: 'true',
    EXECUTOR_SNAPSHOTS_ENABLED: 'true',
    OPENAI_API_KEY: 'controller-key',
    OPENAI_AGENT_ID: 'agent_1',
    OPENAI_WEBHOOK_SECRET: WEBHOOK_SECRET,
    ...overrides
  } as unknown as Env;
  return { env, executor, getByName };
}

function actionRequiredEvent() {
  return {
    ...envelope,
    type: 'agent.session.action_required',
    data: {
      id: 'sess_1',
      required_action: { type: 'environment_connection' }
    }
  };
}

function createdEvent() {
  return {
    ...envelope,
    type: 'agent.session.created',
    data: {
      id: 'sess_1',
      environment_id: 'env_1',
      environment_type: 'self_hosted',
      connect: { remote_url: 'https://api.openai.com/v1/agents/api' }
    }
  };
}

beforeEach(() => resetSpanAttributes());

describe('webhook routing', () => {
  it('records the caught error message on the failing span', async () => {
    const { env, executor } = executorFixture();
    executor.update.mockRejectedValueOnce(
      new Error('Container startup failed')
    );

    const response = await worker.fetch(
      signedWebhook(actionRequiredEvent()),
      env
    );

    expect(response.status).toBe(500);
    expect(spanAttributes).toContainEqual([
      'openai.webhook.type',
      'agent.session.action_required'
    ]);
    expect(spanAttributes).toContainEqual(['openai.webhook.data.id', 'sess_1']);
    expect(spanAttributes).toContainEqual(['error', true]);
    expect(spanAttributes).toContainEqual([
      'error.message',
      'Container startup failed'
    ]);
  });

  it('does not update an executor for a function-call action', async () => {
    const { env, executor } = executorFixture();

    const response = await worker.fetch(
      signedWebhook({
        ...envelope,
        type: 'agent.session.action_required',
        data: {
          id: 'sess_1',
          required_action: { type: 'function_call' }
        }
      }),
      env
    );

    expect(response.status).toBe(200);
    expect(executor.update).not.toHaveBeenCalled();
  });

  it('prewarms a self-hosted created event by default', async () => {
    const { env, executor } = executorFixture();

    const response = await worker.fetch(signedWebhook(createdEvent()), env);

    expect(response.status).toBe(200);
    expect(executor.prewarm).toHaveBeenCalledWith('sess_1');
    expect(executor.update).not.toHaveBeenCalled();
  });

  it('delegates created-event prewarming policy to the Durable Object', async () => {
    const { env, executor } = executorFixture();

    const response = await worker.fetch(signedWebhook(createdEvent()), env);

    expect(response.status).toBe(200);
    expect(executor.prewarm).toHaveBeenCalledWith('sess_1');
  });

  it.each(['agent.session.in_progress', 'agent.session.idle'] as const)(
    're-arms the deadline for %s',
    async (type) => {
      const { env, executor } = executorFixture();

      const response = await worker.fetch(
        signedWebhook({
          ...envelope,
          type,
          data: {
            id: 'sess_1',
            environment_id: 'env_1',
            environment_type: 'self_hosted'
          }
        }),
        env
      );

      expect(response.status).toBe(200);
      expect(executor.update).toHaveBeenCalledWith('sess_1');
    }
  );

  it('rejects a malformed supported event and traces the validation error', async () => {
    const { env, getByName } = executorFixture();

    const response = await worker.fetch(
      signedWebhook({
        ...envelope,
        type: 'agent.session.idle',
        data: { id: 'sess_1', environment_type: 'self_hosted' },
        created_at: 'invalid'
      }),
      env
    );

    expect(response.status).toBe(400);
    expect(getByName).not.toHaveBeenCalled();
    expect(spanAttributes).toContainEqual(['error', true]);
    expect(
      spanAttributes.some(
        ([name, value]) =>
          name === 'error.message' && String(value).includes('created_at')
      )
    ).toBe(true);
  });

  it('acknowledges an unknown future event without creating a stub', async () => {
    const { env, getByName } = executorFixture();

    const response = await worker.fetch(
      signedWebhook({
        ...envelope,
        type: 'agent.session.future_state',
        data: { id: 'sess_1', secret: 'must-not-be-traced' }
      }),
      env
    );

    expect(response.status).toBe(200);
    expect(getByName).not.toHaveBeenCalled();
    expect(spanAttributes.flat()).not.toContain('must-not-be-traced');
  });
});

import { describe, expect, expectTypeOf, it } from "vite-plus/test";

import * as sandbox from "../src/index.js";
import type {
  DirectoryBackupGatewayBinding,
  DirectoryBackupOperation,
  DirectoryBackupRecord,
  S3GatewayBinding,
  S3MountOperation,
  S3MountOperationOptions,
  SandboxBackupErrorCode,
  SandboxS3MountErrorCode,
} from "../src/index.js";

describe("public API", () => {
  it("exports the supported filesystem APIs and error recognizers", () => {
    expect(Object.keys(sandbox).sort()).toEqual([
      "DirectoryBackup",
      "DirectoryBackupGateway",
      "Files",
      "S3Gateway",
      "S3Mount",
      "SandboxBackupError",
      "SandboxFileError",
      "SandboxProtocolError",
      "SandboxS3MountError",
    ]);
  });

  it("exports the directory backup record and error types", () => {
    expectTypeOf<DirectoryBackupGatewayBinding>().toBeFunction();
    expectTypeOf<DirectoryBackupRecord>().toEqualTypeOf<{
      readonly id: string;
      readonly dir: string;
      readonly size: number;
      readonly name?: string;
      readonly sha256: string;
      readonly format: "tar+zstd/1";
    }>();
    expectTypeOf<DirectoryBackupOperation>().toEqualTypeOf<"backup" | "restore" | "delete">();
    expectTypeOf<SandboxBackupErrorCode>().toEqualTypeOf<
      "BACKUP_NOT_FOUND" | "BACKUP_INTEGRITY" | "BACKUP_TRANSFER"
    >();
  });

  it("exports types needed to wrap mount lifecycle operations", () => {
    expectTypeOf<S3GatewayBinding>().toBeFunction();
    expectTypeOf<S3MountOperationOptions>().toMatchTypeOf<{ signal?: AbortSignal }>();
    expectTypeOf<S3MountOperation>().toEqualTypeOf<"mount" | "inspect" | "unmount">();
    expectTypeOf<SandboxS3MountErrorCode>().toEqualTypeOf<
      "S3_MOUNT_CONFLICT" | "S3_MOUNT_BUSY" | "S3_MOUNT_FAILED" | "S3_MOUNT_INCOMPATIBLE"
    >();
  });
});

import { describe, expect, it } from 'vitest';
import { parseOpenAISession, parseWebhookEvent } from '../src/openai-session';

const envelope = {
  id: 'evt_123',
  object: 'event',
  created_at: 1_750_287_018
} as const;

function createdEvent(overrides: Record<string, unknown> = {}) {
  return {
    ...envelope,
    type: 'agent.session.created',
    data: {
      id: 'sess_abc123',
      environment_id: 'ccarenv_abc123',
      environment_type: 'self_hosted',
      connect: {
        remote_url: 'https://api.openai.com/v1/agents/api'
      },
      ...overrides
    }
  };
}

describe('parseOpenAISession', () => {
  it('maps current executor connection state', () => {
    expect(
      parseOpenAISession({
        status: 'requires_action',
        agent: { id: 'agent_1' },
        environment: {
          type: 'self_hosted',
          id: 'env_1',
          remote_url: 'https://api.openai.com/v1/agents/api'
        },
        required_actions: [
          { type: 'environment_connection', environment_id: 'env_1' }
        ]
      })
    ).toEqual({
      status: 'requires_action',
      agentID: 'agent_1',
      environmentType: 'self_hosted',
      environmentID: 'env_1',
      remoteURL: 'https://api.openai.com/v1/agents/api',
      requiredActions: [
        { type: 'environment_connection', environmentID: 'env_1' }
      ]
    });
  });

  it('defaults omitted required actions to an empty list', () => {
    expect(
      parseOpenAISession({
        status: 'idle',
        agent: { id: 'agent_1' },
        environment: { type: 'self_hosted' }
      }).requiredActions
    ).toEqual([]);
  });

  it('rejects malformed session payloads', () => {
    expect(() =>
      parseOpenAISession({
        status: 'in_progress',
        agent: {},
        environment: { type: 'self_hosted' }
      })
    ).toThrow();
  });

  it('rejects an unknown session status', () => {
    expect(() =>
      parseOpenAISession({
        status: 'future_status',
        agent: { id: 'agent_1' },
        environment: { type: 'self_hosted' }
      })
    ).toThrow();
  });
});

describe('parseWebhookEvent', () => {
  it('parses the self-hosted created example', () => {
    const event = createdEvent();
    expect(parseWebhookEvent(event)).toEqual(event);
  });

  it.each(['function_call', 'environment_connection'] as const)(
    'parses the %s action-required example',
    (type) => {
      const event = {
        ...envelope,
        type: 'agent.session.action_required',
        data: {
          id: 'sess_abc123',
          required_action: { type }
        }
      };
      expect(parseWebhookEvent(event)).toEqual(event);
    }
  );

  it.each([
    'agent.session.in_progress',
    'agent.session.idle',
    'agent.session.failed'
  ] as const)('parses the %s example', (type) => {
    const event = {
      ...envelope,
      type,
      data: {
        id: 'sess_abc123',
        environment_id: 'ccarenv_abc123',
        environment_type: 'self_hosted'
      }
    };
    expect(parseWebhookEvent(event)).toEqual(event);
  });

  it.each([
    ['environment_id', createdEvent({ environment_id: undefined })],
    ['connect', createdEvent({ connect: undefined })],
    ['remote_url', createdEvent({ connect: {} })],
    ['null environment_id', createdEvent({ environment_id: null })]
  ])(
    'rejects a malformed supported created event without %s',
    (_name, event) => {
      expect(() => parseWebhookEvent(event)).toThrow();
    }
  );

  it('rejects a supported event with missing envelope fields', () => {
    expect(() =>
      parseWebhookEvent({
        type: 'agent.session.idle',
        data: {
          id: 'sess_abc123',
          environment_type: 'self_hosted'
        }
      })
    ).toThrow();
  });

  it('rejects null instead of an omitted optional environment ID', () => {
    expect(() =>
      parseWebhookEvent({
        ...envelope,
        type: 'agent.session.idle',
        data: {
          id: 'sess_abc123',
          environment_id: null,
          environment_type: 'self_hosted'
        }
      })
    ).toThrow();
  });

  it('ignores an unknown future event type', () => {
    expect(
      parseWebhookEvent({
        ...envelope,
        type: 'agent.session.future_state',
        data: { id: 'sess_abc123' }
      })
    ).toBeUndefined();
  });
});

